      const content = fs.readFileSync(fullPath, 'utf8');
      const { meta, body, rawContent } = extractInstructionFrontmatter(content, sourcePath);
      const unit = compileInstructionUnit(meta, body, rawContent, {
        projectRoot,
        fullPath,
        sourcePath,
