  if (!options.allowDuplicates) {
    for (const unit of collected) {
      if (!idToPaths.has(unit.id)) {
        idToPaths.set(unit.id, [unit.sourcePath]);
      } else {
        idToPaths.get(unit.id).push(unit.sourcePath);
      }
    }

    for (const [id, paths] of idToPaths.entries()) {
      if (paths.length > 1) {
